/**
 * The capability-atlas MCP server (GENERATED — do not edit by hand).
 *
 * Generated by `npm run generate:atlas-server` from
 * lib/capability-atlas/server-entry.ts + lib/capability-atlas/retrieval/*.
 * The server is written into the user's VM next to the role-switch server
 * and exposed to the agent as the `capability-atlas` MCP server. It reads
 * the registry JSON published in the VM ($HOME/.swarm/atlas/registry.json,
 * or SWARM_ATLAS_REGISTRY when set) and serves find_capability /
 * describe_capability over it. Node builtins only; registry entries are
 * shape-checked and projected to scalar fields, so no secret value can
 * ever be served.
 */

/** Name of the stdio MCP server exposing find_capability/describe_capability. */
export const ATLAS_MCP_SERVER_NAME = "capability-atlas";

/** Path (inside the VM) the server is written to. */
export const ATLAS_MCP_SERVER_PATH = "/workspace/.swarm/atlas-server.mjs";

/** The tool the agent calls to find capabilities. */
export const ATLAS_FIND_TOOL = "find_capability";

/** The tool the agent calls to describe one capability. */
export const ATLAS_DESCRIBE_TOOL = "describe_capability";

/** The server program, written verbatim into the VM. */
export function atlasMcpServerSource(): string {
  return [
    "const STOP_WORDS = new Set([",
    "    \"a\", \"an\", \"the\", \"to\", \"for\", \"of\", \"in\", \"on\", \"at\", \"by\", \"with\",",
    "    \"from\", \"and\", \"or\", \"is\", \"are\", \"be\", \"this\", \"that\", \"it\", \"my\",",
    "]);",
    "function tokenize(text) {",
    "    return text",
    "        .toLowerCase()",
    "        .replace(/([a-z])([A-Z])/g, \"$1 $2\")",
    "        .split(/[^a-z0-9+#.-]+/)",
    "        .flatMap((tok) => {",
    "        const cleaned = tok.replace(/^[.-]+|[.-]+$/g, \"\");",
    "        if (!cleaned)",
    "            return [];",
    "        const parts = cleaned.split(/[._-]/).filter(Boolean);",
    "        return parts.length > 1 ? [cleaned, ...parts] : [cleaned];",
    "    })",
    "        .filter((t) => t.length > 1 && !STOP_WORDS.has(t));",
    "}",
    "class Bm25Index {",
    "    docs = [];",
    "    df = new Map();",
    "    avgdl = 0;",
    "    k1 = 1.5;",
    "    b = 0.75;",
    "    constructor(documents) {",
    "        let totalLen = 0;",
    "        for (const doc of documents) {",
    "            const tf = new Map();",
    "            const addTokens = (text, weight) => {",
    "                for (const tok of tokenize(text)) {",
    "                    tf.set(tok, (tf.get(tok) ?? 0) + weight);",
    "                }",
    "            };",
    "            addTokens(doc.fields.name, 3);",
    "            addTokens(doc.fields.summary, 2);",
    "            addTokens(doc.fields.kind, 1);",
    "            if (doc.fields.extra)",
    "                addTokens(doc.fields.extra, 1);",
    "            let length = 0;",
    "            for (const [term, count] of tf.entries()) {",
    "                length += count;",
    "                this.df.set(term, (this.df.get(term) ?? 0) + 1);",
    "            }",
    "            totalLen += length;",
    "            this.docs.push({ id: doc.id, tf, length });",
    "        }",
    "        this.avgdl = this.docs.length > 0 ? totalLen / this.docs.length : 1;",
    "    }",
    "    search(query, k = 5) {",
    "        const qTokens = tokenize(query);",
    "        if (qTokens.length === 0)",
    "            return [];",
    "        const N = this.docs.length;",
    "        const scores = [];",
    "        for (const doc of this.docs) {",
    "            let score = 0;",
    "            for (const term of qTokens) {",
    "                const freq = doc.tf.get(term) ?? 0;",
    "                if (freq === 0)",
    "                    continue;",
    "                const df = this.df.get(term) ?? 0;",
    "                const idf = Math.log(1 + (N - df + 0.5) / (df + 0.5));",
    "                const num = freq * (this.k1 + 1);",
    "                const den = freq + this.k1 * (1 - this.b + this.b * (doc.length / this.avgdl));",
    "                score += idf * (num / den);",
    "            }",
    "            if (score > 0)",
    "                scores.push({ id: doc.id, score });",
    "        }",
    "        scores.sort((a, b) => b.score - a.score);",
    "        return scores.slice(0, k);",
    "    }",
    "}",
    "",
    "/**",
    " * Zero-network local character n-gram + token hashing embedder.",
    " * Produces normalized dense Float32Array vectors for cosine similarity.",
    " */",
    "class LocalEmbedder {",
    "    dim;",
    "    constructor(dim = 256) {",
    "        this.dim = dim;",
    "    }",
    "    hash(str) {",
    "        let h = 2166136261;",
    "        for (let i = 0; i < str.length; i++) {",
    "            h ^= str.charCodeAt(i);",
    "            h = Math.imul(h, 16777619);",
    "        }",
    "        return h >>> 0;",
    "    }",
    "    embed(text) {",
    "        const vec = new Float32Array(this.dim);",
    "        const tokens = tokenize(text);",
    "        for (const tok of tokens) {",
    "            const idx = this.hash(tok) % this.dim;",
    "            const sign = (this.hash(`${tok}#s`) & 1) === 0 ? 1 : -1;",
    "            vec[idx] = (vec[idx] ?? 0) + sign * 2.0;",
    "            // Character 3-grams for morphological tolerance (e.g. render/rendering)",
    "            const padded = `^${tok}$`;",
    "            for (let i = 0; i <= padded.length - 3; i++) {",
    "                const gram = padded.slice(i, i + 3);",
    "                const gIdx = this.hash(gram) % this.dim;",
    "                const gSign = (this.hash(`${gram}#g`) & 1) === 0 ? 1 : -1;",
    "                vec[gIdx] = (vec[gIdx] ?? 0) + gSign * 0.5;",
    "            }",
    "        }",
    "        let norm = 0;",
    "        for (let i = 0; i < this.dim; i++)",
    "            norm += (vec[i] ?? 0) ** 2;",
    "        norm = Math.sqrt(norm) || 1;",
    "        for (let i = 0; i < this.dim; i++)",
    "            vec[i] = (vec[i] ?? 0) / norm;",
    "        return vec;",
    "    }",
    "    cosine(a, b) {",
    "        let dot = 0;",
    "        for (let i = 0; i < this.dim; i++) {",
    "            dot += (a[i] ?? 0) * (b[i] ?? 0);",
    "        }",
    "        return dot;",
    "    }",
    "}",
    "",
    "function estimateTokens(text) {",
    "    return Math.ceil(text.length / 4);",
    "}",
    "class CapabilityRetriever {",
    "    byId = new Map();",
    "    bm25;",
    "    embedder;",
    "    vectors = new Map();",
    "    constructor(entries, options = {}) {",
    "        for (const e of entries)",
    "            this.byId.set(e.id, e);",
    "        this.bm25 = new Bm25Index(entries.map((e) => ({",
    "            id: e.id,",
    "            fields: {",
    "                name: e.name,",
    "                summary: e.summary,",
    "                kind: e.kind,",
    "                extra: e.source,",
    "            },",
    "        })));",
    "        if (options.useLocalEmbeddings) {",
    "            this.embedder = new LocalEmbedder(256);",
    "            for (const e of entries) {",
    "                this.vectors.set(e.id, this.embedder.embed(`${e.name} ${e.summary}`));",
    "            }",
    "        }",
    "    }",
    "    find_capability(query, k = 5) {",
    "        const bm25Hits = this.bm25.search(query, Math.max(k * 3, 15));",
    "        if (!this.embedder) {",
    "            return bm25Hits.slice(0, k).map(({ id, score }) => {",
    "                const entry = this.byId.get(id);",
    "                return {",
    "                    id: entry.id,",
    "                    kind: entry.kind,",
    "                    risk: entry.risk,",
    "                    summary: entry.summary,",
    "                    score: Number(score.toFixed(4)),",
    "                };",
    "            });",
    "        }",
    "        // Hybrid Reciprocal Rank Fusion (BM25 + Local Embeddings)",
    "        const qVec = this.embedder.embed(query);",
    "        const vecHits = [];",
    "        for (const [id, vec] of this.vectors.entries()) {",
    "            const sim = this.embedder.cosine(qVec, vec);",
    "            if (sim > 0.05)",
    "                vecHits.push({ id, score: sim });",
    "        }",
    "        vecHits.sort((a, b) => b.score - a.score);",
    "        const rrf = new Map();",
    "        bm25Hits.forEach((h, idx) => {",
    "            rrf.set(h.id, (rrf.get(h.id) ?? 0) + 1.5 / (60 + idx + 1));",
    "        });",
    "        vecHits.slice(0, Math.max(k * 3, 15)).forEach((h, idx) => {",
    "            rrf.set(h.id, (rrf.get(h.id) ?? 0) + 0.7 / (60 + idx + 1));",
    "        });",
    "        return Array.from(rrf.entries())",
    "            .sort((a, b) => b[1] - a[1])",
    "            .slice(0, k)",
    "            .map(([id, score]) => {",
    "            const entry = this.byId.get(id);",
    "            return {",
    "                id: entry.id,",
    "                kind: entry.kind,",
    "                risk: entry.risk,",
    "                summary: entry.summary,",
    "                score: Number(score.toFixed(4)),",
    "            };",
    "        });",
    "    }",
    "    describe_capability(id) {",
    "        return this.byId.get(id) ?? null;",
    "    }",
    "    formatCompact(results) {",
    "        if (results.length === 0)",
    "            return \"No matching capabilities found.\";",
    "        return results",
    "            .map((r) => `${r.id} | ${r.kind} | ${r.risk} | ${r.summary}`)",
    "            .join(\"\\n\");",
    "    }",
    "}",
    "",
    "/**",
    " * In-VM atlas query server program source.",
    " *",
    " * This file is NOT imported by the app at runtime. It is bundled by",
    " * `generate-server-source.ts` into `lib/harness/atlas-mcp-source.ts`,",
    " * whose output is written verbatim into the user's VM as the",
    " * `capability-atlas` MCP stdio server. Keep it dependency-free apart",
    " * from node builtins and the retrieval modules: the generator refuses",
    " * any other import. The registry path comes from SWARM_ATLAS_REGISTRY",
    " * (set by the harness MCP config); without it, the server reads the",
    " * per-user default under $HOME — never a shared path, never key values.",
    " */",
    "import fs from \"node:fs\";",
    "import path from \"node:path\";",
    "import readline from \"node:readline\";",
    "const KINDS = new Set([",
    "    \"mcp_tool\",",
    "    \"mcp_resource\",",
    "    \"mcp_prompt\",",
    "    \"cli\",",
    "    \"desktop_app\",",
    "    \"ai_provider\",",
    "]);",
    "const RISKS = new Set([\"read-only\", \"writes-files\", \"network\", \"destructive\"]);",
    "function isRecord(v) {",
    "    return typeof v === \"object\" && v !== null && !Array.isArray(v);",
    "}",
    "function toPublicEntry(v) {",
    "    if (!isRecord(v))",
    "        return null;",
    "    const { id, kind, name, summary, risk, source } = v;",
    "    if (typeof id !== \"string\" ||",
    "        id.length === 0 ||",
    "        typeof kind !== \"string\" ||",
    "        !KINDS.has(kind) ||",
    "        typeof name !== \"string\" ||",
    "        name.length === 0 ||",
    "        typeof summary !== \"string\" ||",
    "        summary.length === 0 ||",
    "        typeof risk !== \"string\" ||",
    "        !RISKS.has(risk) ||",
    "        typeof source !== \"string\" ||",
    "        source.length === 0) {",
    "        return null;",
    "    }",
    "    return {",
    "        id,",
    "        kind: kind,",
    "        name,",
    "        summary,",
    "        risk: risk,",
    "        source,",
    "    };",
    "}",
    "function loadRegistry(filePath) {",
    "    try {",
    "        const parsed = JSON.parse(fs.readFileSync(filePath, \"utf8\"));",
    "        if (!isRecord(parsed) || !Array.isArray(parsed.entries))",
    "            return [];",
    "        const out = [];",
    "        for (const e of parsed.entries) {",
    "            const pub = toPublicEntry(e);",
    "            if (pub)",
    "                out.push(pub);",
    "        }",
    "        return out;",
    "    }",
    "    catch {",
    "        return [];",
    "    }",
    "}",
    "function defaultRegistryPath() {",
    "    return path.join(process.env.HOME ?? \"/root\", \".swarm\", \"atlas\", \"registry.json\");",
    "}",
    "const registryPath = process.argv[2] ?? process.env.SWARM_ATLAS_REGISTRY ?? defaultRegistryPath();",
    "const entries = loadRegistry(registryPath);",
    "const retriever = new CapabilityRetriever(entries);",
    "function textResult(id, text) {",
    "    process.stdout.write(`${JSON.stringify({ jsonrpc: \"2.0\", id, result: { content: [{ type: \"text\", text }] } })}\\n`);",
    "}",
    "function errorResult(id, code, message) {",
    "    process.stdout.write(`${JSON.stringify({ jsonrpc: \"2.0\", id, error: { code, message } })}\\n`);",
    "}",
    "const TOOLS = [",
    "    {",
    "        name: \"find_capability\",",
    "        description: \"Find capabilities (MCP tools, CLIs, apps, providers) matching a query. Returns compact id | kind | risk | summary lines.\",",
    "        inputSchema: {",
    "            type: \"object\",",
    "            properties: {",
    "                query: { type: \"string\" },",
    "                k: { type: \"number\", default: 5 },",
    "            },",
    "            required: [\"query\"],",
    "        },",
    "    },",
    "    {",
    "        name: \"describe_capability\",",
    "        description: \"Full discovery metadata for one capability by id.\",",
    "        inputSchema: {",
    "            type: \"object\",",
    "            properties: { id: { type: \"string\" } },",
    "            required: [\"id\"],",
    "        },",
    "    },",
    "];",
    "const rl = readline.createInterface({ input: process.stdin, terminal: false });",
    "rl.on(\"line\", (line) => {",
    "    if (!line.trim())",
    "        return;",
    "    let msg;",
    "    try {",
    "        msg = JSON.parse(line);",
    "    }",
    "    catch {",
    "        return;",
    "    }",
    "    if (!isRecord(msg) || typeof msg.method !== \"string\")",
    "        return;",
    "    const id = msg.id ?? null;",
    "    // Notifications (no id) need no reply.",
    "    if (id === null && msg.method !== \"initialize\")",
    "        return;",
    "    if (msg.method === \"initialize\") {",
    "        process.stdout.write(`${JSON.stringify({",
    "            jsonrpc: \"2.0\",",
    "            id,",
    "            result: {",
    "                protocolVersion: \"2024-11-05\",",
    "                capabilities: { tools: {} },",
    "                serverInfo: { name: \"capability-atlas\", version: \"1.0.0\" },",
    "            },",
    "        })}\\n`);",
    "        return;",
    "    }",
    "    if (msg.method === \"tools/list\") {",
    "        process.stdout.write(`${JSON.stringify({ jsonrpc: \"2.0\", id, result: { tools: TOOLS } })}\\n`);",
    "        return;",
    "    }",
    "    if (msg.method !== \"tools/call\") {",
    "        errorResult(id, -32601, `method not found: ${msg.method}`);",
    "        return;",
    "    }",
    "    const params = isRecord(msg.params) ? msg.params : {};",
    "    const name = params.name;",
    "    const args = isRecord(params.arguments) ? params.arguments : {};",
    "    if (name === \"find_capability\") {",
    "        if (typeof args.query !== \"string\" || args.query.trim() === \"\") {",
    "            errorResult(id, -32602, \"find_capability requires a non-empty query string\");",
    "            return;",
    "        }",
    "        const k = typeof args.k === \"number\" && Number.isFinite(args.k)",
    "            ? Math.min(10, Math.max(1, Math.floor(args.k)))",
    "            : 5;",
    "        textResult(id, retriever.formatCompact(retriever.find_capability(args.query, k)));",
    "        return;",
    "    }",
    "    if (name === \"describe_capability\") {",
    "        if (typeof args.id !== \"string\") {",
    "            errorResult(id, -32602, \"describe_capability requires an id string\");",
    "            return;",
    "        }",
    "        const entry = retriever.describe_capability(args.id);",
    "        textResult(id, entry ? JSON.stringify(entry, null, 2) : \"No such capability.\");",
    "        return;",
    "    }",
    "    errorResult(id, -32602, `unknown tool: ${String(name)}`);",
    "});",
    "",
  ].join("\n");
}
